using ModelContextProtocol;
using PowerShapeMcp;
using Xunit;
namespace PowerShapeMcp.Tests;
public sealed class ReturnedSetReconciliationTests
{
 static Fixture Config(bool enabled=true){var f=new Fixture();foreach(string k in new[]{"returnedSurfaceSetObservationExperimental","ownedSurfaceSetRotationsExperimental","ownedOpenAccessRestoreExperimental","workingCopyOpenExperimental","ownedSurfaceRotationsExperimental","rotationPlansExperimental","ownedRotationPlansExperimental","ownedSurfaceSetTranslationsExperimental","ownedSurfaceTranslationsExperimental","surfaceSamplingExperimental","ownedTranslationsExperimental","ownedOperationPlansExperimental","operationPlansExperimental","entitySetsExperimental","workingCopiesExperimental","documentBindingsExperimental"})f.Config[k]=true;f.Config["returnedSurfaceSetReconciliationExperimental"]=enabled;f.SaveConfig();return f;}
 [Theory][InlineData(false,true,2)][InlineData(false,false,0)][InlineData(true,true,0)]public void FullOnlyNewGate(bool ro,bool enabled,int count){var f=Config(enabled);using var s=new BridgeSession(f.Options(ro));Assert.Equal(count,ReturnedSurfaceSetReconciliationTools.Create(s).Length);}
 [Fact]public void ExplicitObserverDependency(){var f=Config();f.Config["returnedSurfaceSetObservationExperimental"]=false;f.SaveConfig();Assert.Throws<InvalidDataException>(()=>f.Options().ReadConfiguration());}
 [Theory][InlineData(1)][InlineData("true")]public void BooleanOnly(object value){var f=Config();f.Config["returnedSurfaceSetReconciliationExperimental"]=System.Text.Json.Nodes.JsonValue.Create(value);f.SaveConfig();Assert.Throws<InvalidDataException>(()=>f.Options().ReadConfiguration());}
 [Fact]public void PublicSchemaAndNoReadOnlyHints(){var f=Config();using var s=new BridgeSession(f.Options());var tools=ReturnedSurfaceSetReconciliationTools.Create(s);Assert.Equal(2,tools.Length);foreach(var tool in tools){Assert.False(tool.ProtocolTool.Annotations!.ReadOnlyHint);Assert.False(tool.ProtocolTool.Annotations.DestructiveHint);Assert.False(tool.ProtocolTool.InputSchema.GetProperty("additionalProperties").GetBoolean());}var begin=tools.Single(t=>t.ProtocolTool.Name==ReturnedSetReconciliationProof.Begin);var p=begin.ProtocolTool.InputSchema.GetProperty("properties");Assert.Equal(9,p.EnumerateObject().Count());foreach(string k in new[]{"executionReceiptSha256","executionPlanSha256","openVerificationReceiptSha256","observationReceiptSha256"}){string pattern=p.GetProperty(k).GetProperty("pattern").GetString()!;Assert.Matches(pattern,new string('a',64));Assert.DoesNotMatch(pattern,new string('a',32));}}
 [Fact]public async Task UnknownNoQueue(){var f=Config();using var s=new BridgeSession(f.Options());var t=new ReturnedSurfaceSetReconciliationTools(s);var r=await t.Reconcile(new('a',32),new('b',64),new('c',64),new('d',32),new('e',64),new('f',32),new('1',64),new('2',32),new('3',32),CancellationToken.None);Assert.True(r.IsError);Assert.False(Directory.Exists(Path.Combine(f.Root,"requests")));}
 [Fact]public async Task ReadOnlyDirectRefusal(){var f=Config();using var s=new BridgeSession(f.Options(true));await Assert.ThrowsAsync<McpProtocolException>(()=>new ReturnedSurfaceSetReconciliationTools(s).Verify(new('a',32),new('b',64),new('c',32),new('d',32),CancellationToken.None));}
}
